     * and returns the new PSBT. Needs a `Spend{max_duffs}` grant for the
     * wallet covering `external_sent`; redeemed after the checks.
     */
    func signPsbt(walletId: String, psbt: Psbt, grantId: String) async throws  -> Psbt
    
    /**
     * Addresses of the wallet's BIP44 account 0 (QT-096 receiving tab), by
     * chain then index.
     */
    func addresses(walletId: String, filter: AddressFilter) async throws  -> [AddressInfo]
    
    /**
     * Stores a payment request on a freshly issued address and returns it.
     * An amount of 0 means "any amount".
     */
    func createReceiveRequest(walletId: String, amount: UInt64?, label: String?, message: String?) async throws  -> ReceiveRequest
    
    /**
     * The first unused receiving address (IOS-053). Hosts re-query after
     * `HistoryChanged`, which is how the shown address rotates once paid.
     */
    func currentReceiveAddress(walletId: String) async throws  -> AddressInfo
    
    func deleteReceiveRequest(walletId: String, id: UInt64) async throws 
    
    /**
     * Issues a receiving address that was never issued before and labels
     * it (dash-qt "Request payment" always uses a fresh address, QT-081).
     * `GapLimit` once every address inside the gap limit is issued.
     */
    func nextReceiveAddress(walletId: String, label: String?) async throws  -> AddressInfo
    
    /**
     * Stored requests, newest first (QT-083).
     */
    func receiveRequests(walletId: String) async throws  -> [ReceiveRequest]
    
    /**
     * The spendable amount of `source` for dash-qt's "Use available
     * balance" (review M-4): put this minus the other recipients' amounts
     * in the entry and set `subtract_fee_from_amount`. Excludes user-locked,
     * reserved, immature and untrusted unconfirmed coins. `fee` is
     * validated only; with subtract-fee the fee comes out of the amount.
     */
    func maxSpendable(walletId: String, source: CoinSource, fee: FeeMode) async throws  -> UInt64
    
    /**
     * A new, empty draft for `wallet_id` (source `Any`, fee
     * `Recommended{target_blocks: 6}`, change `Auto`).
     */
    func newTxDraft(walletId: String) throws  -> TxDraft
    
    /**
     * `false` after the engine closed this network.
     */
    func isOpen()  -> Bool
    
    func network()  -> DashNetwork
    
    /**
     * Whether the trusted quorum provider is available for Platform proofs.
     */
    func platformContextReady()  -> Bool
    
    func spvRunning() throws  -> Bool
    
    func startSpv() async throws 
    
    func stopSpv() async throws 
    
    /**
